INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('95ae0e6e-1db8-45a1-b834-58094c31ada5', 'Incremento de Renta', '4', '5', 'AUMENTO DE RENTA', E'- The monthly sublease payment for the commercial area will increase annually every January.\n- The first increase will occur in January 2027.\n- The increase will match the rise in the National Consumer Price Index published by INEGI or any replacement index for measuring inflation in Mexico.\n- Annual increases are capped at a maximum of 8% of the current payment amount.', 'El importe de la contraprestación mensual por el subarrendamiento de EL ÁREA COMERCIAL se incrementará Anualmente, durante los meses de enero de cada año, siendo el primer incremento hasta el mes de enero del año 2027, en la misma proporción en que aumente el Indice Nacional de Precios al Consumidor que publique el INEGI (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos), en la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8% del valor de la contraprestación vigente que opere en dicho período.');
