INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('6624ec47-f09d-4b0d-a9ee-522dfcce100b', '00b3d37f-3ad5-4cc7-8e2b-750201f54333', '524af202-0047-4465-aec4-e5620835d44b', 'Monterrey (La Estanzuela) Sublease: Tiendas Soriana, S.A. De C.V. (10/01/2018 - 03/31/2029)', NULL, true, 'activo', 'Lease', NULL, '2019-04-01', '2018-07-01', '2029-03-31', '2049-03-31', false, 4, NULL, 4, NULL, NULL, '2028-09-30', 'Send Notice to Decline', 125, 'Tiendas Soriana, S.A. De C.V.', NULL, NULL, '3102 Avenida Alejandro De Rodas', 'A', 'Monterrey', 'MX-NLE', '64610', 'MX', 'Marcela Pérez Olivas', '818-329-9048', NULL, 182, 'percent', NULL, 487524.8, 840560, 'PLANET FITNESS pagará a SORIANA de forma anticipada, la contraprestación pactada en el párrafo que antecede, pagando el primer mes de renta a la firma del presente contrato, y la segunda renta, dentro de los 45 (cuarenta y cinco) días naturales siguientes al término del periodo de gracia.', NULL, false, '{"tenant_company_addr2":"Piso 1","lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
