INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('6624ec47-f09d-4b0d-a9ee-522dfcce100b', 'Fecha de Firma del Contrato', '20 de mayo de 2018', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6624ec47-f09d-4b0d-a9ee-522dfcce100b', 'Late Fees', '16', '3', 'CONTRAPRESTACIÓN', E'- PLANET FITNESS must pay rent at a SORIANA store checkout or any SANTANDER bank branch.\n- Payment should be made within the first 15 days of the month.\n- If payment is late, starting from the 16th day, a 7% monthly late fee will be added.\n- Any payments made will first cover the interest, then the remaining amount will go towards the rent owed.', 'PLANET FITNESS deberá presentar la factura de renta para su pago únicamente en línea de cajas de la tienda SORIANA o en cualquier sucursal del banco SANTANDER, dentro de los primeros 15 (quince) días naturales del mes que corresponda, sobre el entendido que a partir del dieciseisavo día se acumularán al saldo insoluto, intereses moratorios, a razón del 7% (siete por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses PLANET FITNESS reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6624ec47-f09d-4b0d-a9ee-522dfcce100b', 'Incremento de Renta', '18', '5', 'AUMENTO DE RENTA', E'- The monthly rent and maintenance fee will be updated and adjusted every calendar year.\n- Updates occur on January 1st each year, starting from January 1, 2020.\n- Adjustments are based on the National Consumer Price Index (INPC) changes published by INEGI.\n- Each year, rent increases by 60% of the INPC percentage change.\n- Every sixth year, starting in January 2024, the remaining 40% of the INPC change is added.\n- This pattern continues throughout the contract, with additional adjustments in 2029, 2034, 2039, and 2044 if the contract is extended.', E'Las Partes convienen que la renta mensual y la cuota de mantenimiento se actualizarán y ajustarán cada año calendario, durante la vigencia del presente Contrato, lo anterior en el entendido que durante el primer día del mes de enero de cada año comenzado a partir del primero de enero de 2020 la renta mensual y la cuota de mantenimiento serán actualizadas y ajustados de conformidad con lo previsto en el párrafo siguiente. Las actualizaciones se calcularán por 12 (doce] meses calendario, el cual comenzará el día del inicio del pago de la renta mensual y concluirá el 31 de diciembre del mismo año, y cuya actualización será calculada en proporción al número de días efectivamente transcurridos entre dichas fechas.\n\nLa renta mensual variará en el mismo porcentaje en que hubiere variado el Índice Nacional de Precios al Consumidor (INPC) que publique el INEGI en el Diario Oficial de la Federación (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos) durante los 12 (doce) meses inmediatos anteriores y que para efectos del párrafo anterior se incrementara anualmente al 60% respecto al porcentaje del INPC detallado en presente párrafo y en el entendido que al 6° (sexto) año que sería en el mes de enero de 2024 (dos mil veinticuatro) se realizara el incremento del 40% restante de cada año al INPC indexado y lo mencionado en este párrafo aplicara para toda la vigencia del presente contrato, es decir la renta se estará incrementando anualmente al 60% respecto al porcentaje del INPC y el otro 40% faltante del INPC de cada año transcurrido se incrementara a INPC indexado cada 5 años (primero en año 2024 (dos mil veinticuatro) y en el supuesto que se siga con la vigencia considerando las prórrogas serian en los años 2029 (dos mil veintinueve), 2034 (dos mil treinta y cuatro), 2039 (dos mil treinta y nueve) y 2044 (dos mil cuarenta y cuatro).');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('6624ec47-f09d-4b0d-a9ee-522dfcce100b', 'Common Area Maintenance Charges', '22', '10', 'DEL MANTENIMIENTO Y PREVENCIÓN DE RIESGOS', E'- Planet Fitness is responsible for maintaining the equipment listed in Annex "C" and must provide Soriana with annual maintenance documentation.\n- Planet Fitness must pay Soriana a maintenance fee for common areas, based on 34.75% of the total leased area.\n- Soriana must provide Planet Fitness with the common area maintenance budget for review and approval within the first 10 days of each calendar year.\n- The maintenance fee cannot exceed 9% of the total monthly rent.\n- If Soriana fails to maintain common areas, Planet Fitness can withhold maintenance payments.\n- Common areas include parking lots, drains, pathways, ramps, entrances, corridors, porches, planters, plazas, stairs, and other shared facilities.\n- Planet Fitness is responsible for the maintenance of the leased property, including its perimeter, walls, and roofs.\n- Soriana is responsible for maintaining the common areas during the contract term.', E'De conformidad con el Alcance en que se está entregando el INMUEBLE; el equipo existente se detalla al presente como Anexo "C" el detalle de los equipos que cuenta el INMUEBLE y que PLANET FITNESS será el único responsable de llevar α cabo los mantenimientos correspondientes y necesarios, FITNESS deberá proporcionar anualmente a SORIANA los documentos que respalden dichos mantenimientos.\n\nPLANET FITNESS se obliga a cubrir a SORIANA como cuata de mantenimiento por uso de las áreas comunes, la cantidad que corresponda al porcentaje de proindiviso basado en el área total arrendada del INMUEBLE, que en la fecha de firma del presente Contrato corresponde al 34.75% (treinta y cuatro punto setenta y cinco por ciento) del área total del Centro Comercial; en el entendido que SORIANA deberá entregar a PLANET FITNESS para revisión y aprobación, dentro de los 10 (diez) primeros días de cada año calendario, el presupuesto de mantenimiento de las áreas comunes y, en el entendido adicional, que la cuota de mantenimiento por uso de áreas comunes que deberá pagar PLANET FITNESS a SORIANA en ningún caso podrá ser mayor al 9% (nueve por ciento) del importe total de la renta mensual.\n\nLas partes acuerdan que en caso de incumplimiento de mantenimiento de áreas comunes, Planet Fitness podrá retener el pago de mantenimiento. Para efecto de este contrato se entiende como áreas comunes los estacionamientos, alcantarillas, vías de comunicación, rampas, entradas, pasillos pórticos, jardineras, plazas, escaleras y cualquier otro equipo de instalación de uso común. El costo del mantenimiento de las áreas comunes incluye el mantenimiento y operación del estacionamiento en todas sus áreas y del resto de las áreas comunes.\n\nPLANET FITNESS se obliga durante la vigencia | the common areas. del presente Contrato, a su costa exclusiva, el cuidado, conservación y mantenimiento que requiera EL INMUEBLE (incluyendo perímetro, paredes y techos y las instalaciones que en ella realice; y, SORIANA se obliga durante la vigencia del presente Contrato, a su costa exclusiva, el cuidado, conservación y mantenimiento que requieran las áreas');
