ull_address":"S/N Carretera México - Acapulco Km 87.5, Local 138, Tulipanes, Cuernavaca, Morelos 62370","map_addr_1":"S/N Carretera México - Acapulco Km 87.5","map_addr_2":"Local 138","map_city_state_zip":"Tulipanes, Cuernavaca, Morelos 62370","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2025-09-25 18:46:06","active_lease_count_over_time":50870,"location_count_over_time":57648,"remaining_rent_liability_over_time":50870}'::jsonb);
