INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('2c055004-d5fe-48f5-886a-6e1f3b65c088', 'Fecha de Firma del Contrato', '1 de diciembre de 2021', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2c055004-d5fe-48f5-886a-6e1f3b65c088', 'Late Fees', '14', '13', 'INTERESES MORATORIOS', E'- The tenant must make all payments on the agreed dates.\n- If a payment is late, the tenant will pay late interest.\n- Late interest is calculated by multiplying 1.33 by the Average Cost of Funds Rate set by the Bank of Mexico.\n- If this rate is below 30%, the late interest rate will be 30% multiplied by 1.33.\n- This interest applies to the total unpaid amount.\n- Interest is calculated monthly by dividing the annual rate by twelve.\n- Late interest is charged if payment is more than ten days late.\n- The interest is calculated for each month or part of a month the payment is late.', E'La Arrendataria se obliga a cumplir con todas y cada una de las obligaciones de pago pactadas en el presente contrato precisamente en las fechas o términos convenidos, y acepta cubrir en el caso de mora de cualquier pago, los intereses moratorios que se calcularán como sigue:\nLa tasa de intereses moratorios resultará de multiplicar por 1.33 el Costo Porcentual Promedio de Captación de la Banca Múltiple estimado por el Banco de México, vigente al momento en que sea exigible el pago de interés moratorio. En el caso de que el costo Porcentual Promedio de Captación de la Banca Múltiple sea inferior al 30%, la tasa de interés moratorio se formará multiplicando 30%, por 1.33. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio se aplicará mensualmente dividiendo entre doce el importe del interés moratorio anual, y será exigible cuando la Arrendataria se retrase en un pago por más de diez días de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2c055004-d5fe-48f5-886a-6e1f3b65c088', 'Incremento de Renta', '6', '4', 'AJUSTE DE LA RENTA', E'- The fixed monthly rent will increase every 12 months from the start date.\n- The increase is based on the change in the National Consumer Price Index (INPC) published by INEGI.\n- The increase cannot exceed 4% of the current fixed monthly rent, unless the tenant extends the contract as per clause three.\n- If the INPC shows a negative change (deflation), the rent will increase by 1%.\n- If INEGI''s indices are not available when the rent adjustment is due, estimated indices will be used temporarily. Once the official indices are published, the final adjustment will be applied retroactively.\n- Rent adjustments do not mean the contract is renewed.\n- If the landlord does not apply a rent increase, it is not considered waived. The tenant must pay any missed increases retroactively.', E'Las Partes convienen que la Renta Mensual Fija pactada en la cláusula Primera, será incrementada cada 12 (doce) meses, contado a partir de la fecha de inicio de vigencia, se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica:\n\na) Se tomará como base, el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste en. la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 4% (cuatro por ciento) del valor de la Renta Mensual Fija vigente que opere en dicho período. Las Partes acuerdan que el presente tope de incremento no aplicará para el ajuste de la Renta Fija en caso de que la Arrendataria prorrogue el presente Contrato en términos de la cláusula Tercera.\n\nb) Si la variación semestral del INPC mostrara porcentajes negativos (deflación), el ajuste se hará en un 1.0% (uno punto por ciento).\n\nEn el caso de que en el mes en que deba efectuarse el ajuste de renta, no estén publicados los índices elaborados por el Instituto Nacional de Estadística y Geografía (INEGI), dicho ajuste se hará provisionalmente con índices estimados hasta que se disponga de la publicación respectiva, momento en que se determinará el ajuste definitivo, mismo que se aplicará retroactivamente a partir del mes de que se trate. Los ajustes en el importe de la renta no darán lugar a que se considere novado el contrato. Las Partes acuerdan que en caso de que la Arrendadora no aplique un incremento de Renta conforme a la presente cláusula, éste no se entenderá como prescrito ni caduco, por lo que la Arrendataria se obliga siempre a pagar la Arrendadora de manera retroactiva los importes correspondientes a dichos incrementos.');
